compact/powershell/windsurf/ollama-embed.copy:
# Keep generated configuration files out of version control.
if (-not (Test-Path .gitignore)) { New-Item -ItemType File -Path .gitignore | Out-Null }
Add-Content -Path .gitignore -Value '.chunkhound.json'
# Configure ChunkHound with Ollama embeddings and Claude Code CLI for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
@'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "claude-code-cli"
  }
}
'@ | Set-Content -Path '.chunkhound.json' -Encoding utf8
# Configure Windsurf to connect to ChunkHound via MCP.
if (Test-Path "$HOME/.codeium/windsurf/mcp_config.json") {
Write-Host @'
$HOME/.codeium/windsurf/mcp_config.json already exists — merge this block into it manually:
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
'@
} else {
New-Item -ItemType Directory -Force -Path "$HOME/.codeium/windsurf" | Out-Null
@'
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
'@ | Set-Content -Path "$HOME/.codeium/windsurf/mcp_config.json" -Encoding utf8
}
# Build ChunkHound's search index for this project.
chunkhound index .

